package com.marketing.analytics.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="creative_asset_performance")
public class CreativeAssetPerformance { @Id UUID id; @Column(nullable=false) UUID creativeAssetId; @Column(nullable=false) UUID businessId; @Column(nullable=false) String platform; Long impressions; Long clicks; Long conversions; BigDecimal spend; BigDecimal revenue; BigDecimal ctr; BigDecimal cpc; BigDecimal cpa; BigDecimal roas; @Column(nullable=false) Instant recordedAt; Instant createdAt; BigDecimal performanceScore; String classification; BigDecimal confidenceScore; @Column(columnDefinition="jsonb") String reasoningJson; Instant updatedAt;
public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getCreativeAssetId(){return creativeAssetId;} public void setCreativeAssetId(UUID v){creativeAssetId=v;} public UUID getBusinessId(){return businessId;} public void setBusinessId(UUID v){businessId=v;} public String getPlatform(){return platform;} public void setPlatform(String v){platform=v;} public Long getImpressions(){return impressions;} public void setImpressions(Long v){impressions=v;} public Long getClicks(){return clicks;} public void setClicks(Long v){clicks=v;} public Long getConversions(){return conversions;} public void setConversions(Long v){conversions=v;} public BigDecimal getSpend(){return spend;} public void setSpend(BigDecimal v){spend=v;} public BigDecimal getRevenue(){return revenue;} public void setRevenue(BigDecimal v){revenue=v;} public BigDecimal getCtr(){return ctr;} public void setCtr(BigDecimal v){ctr=v;} public BigDecimal getCpc(){return cpc;} public void setCpc(BigDecimal v){cpc=v;} public BigDecimal getCpa(){return cpa;} public void setCpa(BigDecimal v){cpa=v;} public BigDecimal getRoas(){return roas;} public void setRoas(BigDecimal v){roas=v;} public Instant getRecordedAt(){return recordedAt;} public void setRecordedAt(Instant v){recordedAt=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public BigDecimal getPerformanceScore(){return performanceScore;} public void setPerformanceScore(BigDecimal v){performanceScore=v;} public String getClassification(){return classification;} public void setClassification(String v){classification=v;} public BigDecimal getConfidenceScore(){return confidenceScore;} public void setConfidenceScore(BigDecimal v){confidenceScore=v;} public String getReasoningJson(){return reasoningJson;} public void setReasoningJson(String v){reasoningJson=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
